<?php
namespace App\Http\Controllers; use App\Models\{PartnerProfile,FoodDonation,FoodRequest,DeliveryTask};
class ApiController extends Controller { private function wrap($data){return response()->json(['status'=>'success','timestamp'=>now()->toISOString(),'data'=>$data]);} public function partnerStatus($id){return $this->wrap(PartnerProfile::findOrFail($id)->only('profile_id','verification_status'));} public function availableDonations(){return $this->wrap(FoodDonation::where('donation_status','AVAILABLE')->where('expiry_datetime','>',now())->get());} public function requestReservations($id){return $this->wrap(FoodRequest::findOrFail($id)->reservations()->with('donation')->get());} public function deliveryStatus($id){return $this->wrap(DeliveryTask::findOrFail($id)->only('delivery_id','delivery_status','picked_up_at','delivered_at'));} }
